using Cleared.Domain.Invoicing;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace Cleared.Infrastructure.Persistence.Configurations;

public sealed class InvoiceLineItemConfiguration : IEntityTypeConfiguration<InvoiceLineItem>
{
    public void Configure(EntityTypeBuilder<InvoiceLineItem> builder)
    {
        builder.ToTable("invoice_line_items");

        builder.HasKey(li => li.Id);

        // The domain gives every line its id. Left to EF, a Guid key is generated by the database, so a line
        // with its id already set that is added to a draft EF is tracking is taken to exist and is updated
        // instead of inserted. Changing a draft does exactly that, so a line is never generated.
        builder.Property(li => li.Id).ValueGeneratedNever();

        // Without it a read returns the lines in the order of their random ids. See Invoice.Lines.
        builder.Property(li => li.Position).IsRequired();

        builder.Property(li => li.Description)
            .IsRequired()
            .HasMaxLength(500);

        builder.Property(li => li.Quantity)
            .HasPrecision(18, 4);

        builder.Property(li => li.VatTreatment)
            .HasConversion<string>()
            .HasMaxLength(20);

        builder.ComplexProperty(li => li.UnitPrice, money =>
        {
            money.Property(m => m.Amount).HasPrecision(18, 2);
            money.Property(m => m.Currency).HasConversion<string>().HasMaxLength(3);
        });

        builder.ComplexProperty(li => li.LineSubtotal, money =>
        {
            money.Property(m => m.Amount).HasPrecision(18, 2);
            money.Property(m => m.Currency).HasConversion<string>().HasMaxLength(3);
        });

        builder.ComplexProperty(li => li.LineVat, money =>
        {
            money.Property(m => m.Amount).HasPrecision(18, 2);
            money.Property(m => m.Currency).HasConversion<string>().HasMaxLength(3);
        });

        // LineTotal is computed (LineSubtotal + LineVat), never stored.
        // See Invoice.Subtotal.
        builder.Ignore(li => li.LineTotal);
    }
}
